using EddaStore.Data;using EddaStore.Models.Customers;using EddaStore.Models.ViewModels.Store;using EddaStore.Services.Interfaces;using Microsoft.EntityFrameworkCore;
namespace EddaStore.Services;
public class CartService(ApplicationDbContext context):ICartService { public async Task<CartViewModel> GetAsync(Guid customerId,CancellationToken ct=default){var cart=await context.Carts.Include(x=>x.Items).ThenInclude(x=>x.Product).ThenInclude(x=>x.Images).FirstOrDefaultAsync(x=>x.CustomerId==customerId,ct);if(cart is null)return new();return new CartViewModel{Items=cart.Items.Where(x=>!x.IsDeleted&&x.Product.IsActive&&!x.Product.IsDeleted).Select(x=>new CartLineViewModel{ProductId=x.ProductId,Name=x.Product.Name,ImageUrl=x.Product.Images.OrderByDescending(i=>i.IsPrimary).ThenBy(i=>i.SortOrder).FirstOrDefault()?.ImageUrl,UnitPrice=x.Product.Price,Quantity=x.Quantity,AvailableQuantity=x.Product.StockQuantity}).ToList()};}public async Task AddAsync(Guid customerId,Guid productId,int quantity,CancellationToken ct=default){if(quantity<1)throw new ArgumentException("الكمية يجب أن تكون قطعة واحدة على الأقل.");var product=await context.Products.FirstOrDefaultAsync(x=>x.Id==productId&&!x.IsDeleted,ct)??throw new KeyNotFoundException();if(!product.IsActive)throw new InvalidOperationException("المنتج غير متوفر حاليًا.");var cart=await context.Carts.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.CustomerId==customerId,ct);if(cart is null){cart=new Cart{CustomerId=customerId};context.Carts.Add(cart);}var item=cart.Items.FirstOrDefault(x=>x.ProductId==productId&&!x.IsDeleted);var requested=(item?.Quantity??0)+quantity;if(requested>product.StockQuantity)throw new InvalidOperationException("الكمية المطلوبة غير متاحة في المخزون.");if(item is null){var newItem=new CartItem{ProductId=productId,Quantity=quantity};cart.Items.Add(newItem);context.CartItems.Add(newItem);}else item.Quantity=requested;await context.SaveChangesAsync(ct);}public async Task UpdateAsync(Guid customerId,Guid productId,int quantity,CancellationToken ct=default){if(quantity<1){await RemoveAsync(customerId,productId,ct);return;}var cart=await context.Carts.Include(x=>x.Items).ThenInclude(x=>x.Product).FirstOrDefaultAsync(x=>x.CustomerId==customerId,ct)??throw new KeyNotFoundException();var item=cart.Items.FirstOrDefault(x=>x.ProductId==productId&&!x.IsDeleted)??throw new KeyNotFoundException();if(!item.Product.IsActive||quantity>item.Product.StockQuantity)throw new InvalidOperationException("الكمية المطلوبة غير متاحة في المخزون.");item.Quantity=quantity;await context.SaveChangesAsync(ct);}public async Task RemoveAsync(Guid customerId,Guid productId,CancellationToken ct=default){var item=await context.CartItems.Include(x=>x.Cart).FirstOrDefaultAsync(x=>x.Cart.CustomerId==customerId&&x.ProductId==productId&&!x.IsDeleted,ct)??throw new KeyNotFoundException();context.CartItems.Remove(item);await context.SaveChangesAsync(ct);}}

